// SubprocessRequest is the API-neutral request data needed by subprocess
// harness runner implementations.
type SubprocessRequest struct {
	Prompt         string
	SystemPrompt   string
	WorkDir        string
	Permissions    string
	Temperature    *float32
	Seed           *int64
	Reasoning      reasoning.Reasoning
	Timeout        time.Duration
	IdleTimeout    time.Duration
	SessionLogDir  string
	Metadata       map[string]string
	Decision       ExecuteRunnerDecision
	Started        time.Time
	SessionLogPath string
}

// SubprocessCallbacks bridge service-owned event/progress/session-log behavior
// without importing root public service types.
type SubprocessCallbacks struct {
	BeforeExecute func()
	BeforeFinal   func(harnesses.FinalData)
	ObserveEvent  func(harnesses.Event) harnesses.Event
	EmitEvent     func(harnesses.Event) bool
	Finalize      func(harnesses.FinalData)
	WriteEnd      func(map[string]string, harnesses.FinalData)
}

// RunSubprocess executes a subprocess harness and forwards its event stream.
func RunSubprocess(ctx context.Context, req SubprocessRequest, runner harnesses.Harness, cb SubprocessCallbacks) {
	hReq := harnesses.ExecuteRequest{
		Prompt:        req.Prompt,
		SystemPrompt:  req.SystemPrompt,
		Provider:      req.Decision.Provider,
		Model:         req.Decision.Model,
		WorkDir:       req.WorkDir,
		Permissions:   req.Permissions,
		Temperature:   subprocessTemperature(req.Temperature),
		Seed:          subprocessSeed(req.Seed),
		Reasoning:     adapterReasoning(req.Reasoning),
		Timeout:       req.Timeout,
		IdleTimeout:   req.IdleTimeout,
		SessionLogDir: req.SessionLogDir,
		Metadata:      req.Metadata,
	}
	if cb.BeforeExecute != nil {
		cb.BeforeExecute()
	}
	in, err := runner.Execute(ctx, hReq)
	if err != nil {
		finalizeSubprocess(cb, harnesses.FinalData{
			Status:     "failed",
			Error:      err.Error(),
			DurationMS: time.Since(req.Started).Milliseconds(),
			RoutingActual: &harnesses.RoutingActual{
				Harness:  req.Decision.Harness,
				Provider: req.Decision.Provider,
				Model:    req.Decision.Model,
			},
		})
		return
	}
	for ev := range in {
		if ev.Metadata == nil {
			ev.Metadata = req.Metadata
		}
		if ev.Type == harnesses.EventTypeFinal {
			var final harnesses.FinalData
			if err := json.Unmarshal(ev.Data, &final); err == nil && cb.BeforeFinal != nil {
				cb.BeforeFinal(final)
			}
			ev = stampSubprocessFinalRouting(ev, req.Decision)
			ev = stampSubprocessFinalSessionLog(ev, req.SessionLogPath)
			if err := json.Unmarshal(ev.Data, &final); err == nil && cb.WriteEnd != nil {
				cb.WriteEnd(req.Metadata, final)
			}
		}
		if cb.ObserveEvent != nil {
			ev = cb.ObserveEvent(ev)
		}
		if cb.EmitEvent != nil && !cb.EmitEvent(ev) {
			return
		}
	}
}

func subprocessTemperature(v *float32) float32 {
	if v == nil {
		return 0
	}
	return *v
}

func subprocessSeed(v *int64) int64 {
	if v == nil {
		return 0
	}
	return *v
}

func adapterReasoning(value reasoning.Reasoning) string {
	policy, err := reasoning.ParseString(string(value))
	if err != nil {
		return string(value)
	}
	switch policy.Kind {
	case reasoning.KindUnset, reasoning.KindAuto, reasoning.KindOff:
		return ""
	case reasoning.KindTokens:
		if policy.Tokens == 0 {
			return ""
		}
		return string(policy.Value)
	case reasoning.KindNamed:
		return string(policy.Value)
	default:
		return string(value)
	}
}

func stampSubprocessFinalSessionLog(ev harnesses.Event, sessionLogPath string) harnesses.Event {
	if sessionLogPath == "" {
		return ev
	}
	var final harnesses.FinalData
	if err := json.Unmarshal(ev.Data, &final); err != nil {
		return ev
	}
	final.SessionLogPath = sessionLogPath
	raw, err := json.Marshal(final)
	if err != nil {
		return ev
	}
	ev.Data = raw
	return ev
}

func stampSubprocessFinalRouting(ev harnesses.Event, decision ExecuteRunnerDecision) harnesses.Event {
	var final harnesses.FinalData
	if err := json.Unmarshal(ev.Data, &final); err != nil {
		return ev
	}
	if final.RoutingActual == nil {
		final.RoutingActual = &harnesses.RoutingActual{
			Harness:  decision.Harness,
			Provider: decision.Provider,
			Model:    decision.Model,
		}
	}
	raw, err := json.Marshal(final)
	if err != nil {
		return ev
	}
	ev.Data = raw
	return ev
}

func finalizeSubprocess(cb SubprocessCallbacks, final harnesses.FinalData) {
	if cb.Finalize != nil {
		cb.Finalize(final)
	}
}

// Package rapidmlx wraps the OpenAI-compatible HTTP surface exposed by
// Rapid-MLX (https://github.com/raullenchai/Rapid-MLX). It is a concrete
// provider type distinct from vLLM so the service layer can keep provider
// identity separate from utilization probing, which Rapid-MLX exposes on a
// different observability endpoint family.
package rapidmlx

import (
	agentcore "github.com/DocumentDrivenDX/fizeau/internal/core"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/openai"
	"github.com/DocumentDrivenDX/fizeau/internal/provider/registry"
	"github.com/DocumentDrivenDX/fizeau/internal/reasoning"
)

const DefaultBaseURL = "http://localhost:8000/v1"

func init() {
	registry.Register(registry.Descriptor{
		Type: "rapid-mlx",
		Factory: func(in registry.Inputs) agentcore.Provider {
			return New(Config{
				BaseURL:      in.BaseURL,
				APIKey:       in.APIKey,
				Model:        in.Model,
				ModelPattern: in.ModelPattern,
				KnownModels:  in.KnownModels,
				Headers:      in.Headers,
				Reasoning:    in.Reasoning,
			})
		},
		DefaultBaseURL: DefaultBaseURL,
		DefaultPort:    8000,
	})
}

// ProtocolCapabilities keeps Rapid-MLX on the standard OpenAI-compatible
// surface. The provider remains distinct from vLLM at the type level.
var ProtocolCapabilities = openai.OpenAIProtocolCapabilities

type Config struct {
	BaseURL      string
	APIKey       string
	Model        string
	ModelPattern string
	KnownModels  map[string]string
	Headers      map[string]string
	Reasoning    reasoning.Reasoning
}

func New(cfg Config) *openai.Provider {
	baseURL := cfg.BaseURL
	if baseURL == "" {
		baseURL = DefaultBaseURL
	}
	return openai.New(openai.Config{
		BaseURL:        baseURL,
		APIKey:         cfg.APIKey,
		Model:          cfg.Model,
		ProviderName:   "rapid-mlx",
		ProviderSystem: "rapid-mlx",
		ModelPattern:   cfg.ModelPattern,
		KnownModels:    cfg.KnownModels,
		Headers:        cfg.Headers,
		Reasoning:      cfg.Reasoning,
		Capabilities:   &ProtocolCapabilities,
	})
}

	if err := c.expandEndpointProviders(); err != nil {
		return err
	}

	for name, pc := range c.Providers {
		normalized := normalizeProviderConfig(pc)
		c.Providers[name] = normalized
	}

	if err := c.validateProviders(); err != nil {
		return err
	}

	if c.CompactionPercent != 0 && (c.CompactionPercent < 1 || c.CompactionPercent > 100) {
		return fmt.Errorf("config: compaction_percent must be 1-100, got %d", c.CompactionPercent)
	}

	return nil
}

func (c *Config) expandEndpointProviders() error {
	if len(c.Endpoints) == 0 {
		return nil
	}
	if c.Providers == nil {
		c.Providers = make(map[string]ProviderConfig, len(c.Endpoints))
	}
	firstGenerated := ""
	used := make(map[string]bool, len(c.Providers)+len(c.Endpoints))
	for name := range c.Providers {
		used[name] = true
	}
	for i, endpoint := range c.Endpoints {
		pc, name, err := providerConfigFromEndpoint(endpoint, i+1)
		if err != nil {
			return err
		}
		name = uniqueEndpointProviderName(name, used)
		used[name] = true
		c.Providers[name] = pc
		if firstGenerated == "" {
			firstGenerated = name
		}
	}
	if c.Default == "" && firstGenerated != "" {
		c.Default = firstGenerated
	}
	return nil
}

func providerConfigFromEndpoint(endpoint EndpointConfig, ordinal int) (ProviderConfig, string, error) {
	providerType := strings.ToLower(strings.TrimSpace(endpoint.Type))
	if providerType == "" {
		providerType = inferProviderTypeFromBaseURL(endpoint.BaseURL)
	}
	if providerType == "" {
		return ProviderConfig{}, "", fmt.Errorf("config: endpoint %d: type is required when base_url does not identify a provider", ordinal)
	}
	baseURL, err := endpointBaseURL(endpoint, providerType)
	if err != nil {
		return ProviderConfig{}, "", fmt.Errorf("config: endpoint %d: %w", ordinal, err)
	}
	name := strings.TrimSpace(endpoint.Name)
	if name == "" {
		name = generatedEndpointProviderName(endpoint, providerType, baseURL, ordinal)
	}
	return ProviderConfig{
		Type:    providerType,
		BaseURL: baseURL,
		Endpoints: []ProviderEndpoint{{
			Name:    "default",
			BaseURL: baseURL,
		}},
		APIKey:    endpoint.APIKey,
		Headers:   endpoint.Headers,
		Reasoning: endpoint.Reasoning,
	}, name, nil
}

func endpointBaseURL(endpoint EndpointConfig, providerType string) (string, error) {
	if baseURL := strings.TrimSpace(endpoint.BaseURL); baseURL != "" {
		return baseURL, nil
	}
	if providerType == "openrouter" {
		return openrouter.DefaultBaseURL, nil
	}
	host := strings.TrimSpace(endpoint.Host)
	if host == "" {
		return "", fmt.Errorf("host or base_url is required")
	}
	port := endpoint.Port
	if port == 0 {
		port = defaultEndpointPort(providerType)
	}
	if port == 0 {
		return "", fmt.Errorf("port is required for provider type %q", providerType)
	}
	if strings.HasPrefix(host, "http://") || strings.HasPrefix(host, "https://") {
		return strings.TrimRight(fmt.Sprintf("%s:%d", strings.TrimRight(host, "/"), port), "/") + "/v1", nil
	}
	return fmt.Sprintf("http://%s:%d/v1", host, port), nil
}

func defaultEndpointPort(providerType string) int {
	switch providerType {
	case "lmstudio":
		return 1234
	case "omlx":
		return 1235
	case "lucebox":
		return 1236
	case "vllm":
		return 8000
	case "ollama":
		return 11434
	default:
		return 0
	}
}

func generatedEndpointProviderName(endpoint EndpointConfig, providerType, baseURL string, ordinal int) string {
	host := strings.TrimSpace(endpoint.Host)
	if host == "" {
		host = strings.TrimSpace(baseURL)
	}
	host = strings.NewReplacer("http://", "", "https://", "", "/v1", "", "/", "-", ":", "-").Replace(host)
	if host == "" {
		return fmt.Sprintf("%s-%d", providerType, ordinal)
	}
	if endpoint.Port > 0 {
		return fmt.Sprintf("%s-%s-%d", providerType, host, endpoint.Port)
	}
	return fmt.Sprintf("%s-%s", providerType, host)
}

func uniqueEndpointProviderName(name string, used map[string]bool) string {
	if !used[name] {
		return name
	}
	for i := 2; ; i++ {
		candidate := fmt.Sprintf("%s-%d", name, i)
		if !used[candidate] {
			return candidate
		}
	}
}

func normalizeProviderConfig(pc ProviderConfig) ProviderConfig {
	pc.Type = strings.ToLower(strings.TrimSpace(pc.Type))
	pc.BaseURL = strings.TrimSpace(pc.BaseURL)
	for i := range pc.Endpoints {
		pc.Endpoints[i].Name = strings.TrimSpace(pc.Endpoints[i].Name)
		pc.Endpoints[i].BaseURL = strings.TrimSpace(pc.Endpoints[i].BaseURL)
	}
	if pc.BaseURL == "" && len(pc.Endpoints) > 0 {
		pc.BaseURL = pc.Endpoints[0].BaseURL
	}
	if pc.Type == "" {
		pc.Type = inferProviderTypeFromBaseURL(pc.BaseURL)
	}
	switch pc.Type {
	case "openrouter":
		if pc.BaseURL == "" {
			pc.BaseURL = openrouter.DefaultBaseURL
		}
	case "openai":
		if pc.BaseURL == "" {
			pc.BaseURL = "https://api.openai.com/v1"
		}
	case "lmstudio":
		if pc.BaseURL == "" {
			pc.BaseURL = lmstudio.DefaultBaseURL
		}
	case "omlx":
		if pc.BaseURL == "" {
			pc.BaseURL = omlx.DefaultBaseURL
		}
	case "lucebox":
		if pc.BaseURL == "" {
			pc.BaseURL = lucebox.DefaultBaseURL
		}
	case "vllm":
		if pc.BaseURL == "" {
			pc.BaseURL = vllm.DefaultBaseURL
		}
	case "rapid-mlx":
		if pc.BaseURL == "" {
			pc.BaseURL = rapidmlx.DefaultBaseURL
		}
	case "ollama":
		if pc.BaseURL == "" {
			pc.BaseURL = ollama.DefaultBaseURL
		}
	}
	if pc.BaseURL != "" && len(pc.Endpoints) == 0 && providerUsesEndpoint(pc.Type) {
		pc.Endpoints = []ProviderEndpoint{{Name: "default", BaseURL: pc.BaseURL}}
	}
	return pc
}

func inferProviderTypeFromBaseURL(baseURL string) string {
	baseURL = strings.TrimSpace(baseURL)
	if baseURL == "" {
		return ""
	}
	low := strings.ToLower(baseURL)
	switch {
	case strings.Contains(low, "openrouter.ai"):
		return "openrouter"
	case strings.Contains(low, "openai.com"):
		return "openai"
	case strings.Contains(low, "minimaxi.chat"):
		return "minimax"
	case strings.Contains(low, "dashscope.aliyuncs.com"):
		return "qwen"
	case strings.Contains(low, "z.ai"):
		return "zai"
	case strings.Contains(low, ":11434"):
		return "ollama"
	case strings.Contains(low, ":1234"):
		return "lmstudio"
	case strings.Contains(low, ":1235"):
		return "omlx"
	case strings.Contains(low, ":1236"):
		return "lucebox"
	case strings.Contains(low, ":8000"):
		return "vllm"
	default:
		return ""
	}
}

func providerUsesEndpoint(providerType string) bool {
	switch providerType {
	case "openai", "openrouter", "lmstudio", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", "minimax", "qwen", "zai":
		return true
	default:
		return false
	}
}

// LoadModelCatalog loads the shared model catalog using the configured manifest override path.
func (c *Config) LoadModelCatalog() (*modelcatalog.Catalog, error) {
	manifestPath := c.ModelCatalog.Manifest
	if strings.TrimSpace(manifestPath) == "" {
		manifestPath = DefaultModelCatalogManifestPath()
	}
	return modelcatalog.Load(modelcatalog.LoadOptions{
		ManifestPath: manifestPath,
	})
}

// ProviderImplicitGenerationConfig reports whether the inference server
// behind the given provider type auto-applies the model's HuggingFace
// generation_config.json when the request omits sampler fields. The CLI
// uses this to tone the ADR-007 §7 catalog-stale nudge — vLLM users with
// no catalog profile aren't decoding greedy, they're getting model-card
// defaults; everyone else is in the loop-bug regime.
//
// The single source of truth is each provider package's
// ProtocolCapabilities; this function exists because cmd/fiz cannot
// import provider packages directly.
func ProviderImplicitGenerationConfig(providerType string) bool {
	switch providerType {
	case "vllm":
		return vllm.ProtocolCapabilities.ImplicitGenerationConfig
	default:
		return false
	}
}

func surfaceForProviderType(providerType string) (modelcatalog.Surface, error) {
	switch providerType {
	case "openai", "openrouter", "lmstudio", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", "minimax", "qwen", "zai":
		return modelcatalog.SurfaceAgentOpenAI, nil
	case "anthropic":
		return modelcatalog.SurfaceAgentAnthropic, nil
	default:
		return "", fmt.Errorf("config: cannot resolve model reference for provider type %q", providerType)
	}
}

// envVarPattern matches ${VAR_NAME} patterns.
var envVarPattern = regexp.MustCompile(`\$\{([A-Za-z_][A-Za-z0-9_]*)\}`)

// expandEnvVars replaces ${VAR} patterns with environment variable values.
func expandEnvVars(s string) string {
	return envVarPattern.ReplaceAllStringFunc(s, func(match string) string {
		varName := strings.TrimSuffix(strings.TrimPrefix(match, "${"), "}")
		if val, ok := os.LookupEnv(varName); ok {
			return val
		}
		return match // leave unexpanded if not set
	})
}

// Save serializes the config to YAML bytes.
func (c *Config) Save() ([]byte, error) {
	// #nosec G117 -- config persistence intentionally serializes configured credentials.
	return yaml.Marshal(c)
}

// Save is a package-level alias for Config.Save.
func Save(cfg *Config) ([]byte, error) {
	return cfg.Save()
}

// SaveToFile writes the config to a YAML file.
func SaveToFile(path string, cfg *Config) error {
	data, err := cfg.Save()
	if err != nil {
		return fmt.Errorf("config: marshaling: %w", err)
	}
	if err := os.WriteFile(path, data, 0600); err != nil {
		return fmt.Errorf("config: writing %s: %w", path, err)
	}
	return nil
}

// validateProviders checks configured provider entries. A config with no
// providers is still loadable because several CLI surfaces do not need a
// runtime provider.
func (c *Config) validateProviders() error {
	if len(c.Providers) == 0 {
		return nil
	}
	for name, pc := range c.Providers {
		if pc.Type == "openai-compat" {
			return fmt.Errorf("config: provider %q: type openai-compat is no longer supported; use openai, openrouter, lmstudio, omlx, rapid-mlx, or ollama", name)
		}
		switch pc.Type {
		case "openai", "openrouter", "lmstudio", "omlx", "lucebox", "vllm", "rapid-mlx", "ollama", "minimax", "qwen", "zai", "anthropic":
		default:
			return fmt.Errorf("config: provider %q has unknown type %q (use openai, openrouter, lmstudio, omlx, luce, vllm, rapid-mlx, ollama, or anthropic)", name, pc.Type)
		}
		if providerUsesEndpoint(pc.Type) {
			for i, endpoint := range pc.Endpoints {
				if endpoint.BaseURL == "" {
					return fmt.Errorf("config: provider %q endpoint %d: base_url is required", name, i+1)
				}
			}
		}
		if (pc.Type == "openai" || pc.Type == "openrouter" || pc.Type == "anthropic") && pc.APIKey == "" {
			return fmt.Errorf("config: provider %q (%s): api_key is required", name, pc.Type)
		}
	}

